# UARD (Untrapped Auto-Repair Diagnostic) ver 1.1.1 - TRUE BASELINE
# Fail-closed client gate: fetch -> syntax -> adaptive repair -> AST equivalence -> install.
# Candidate PowerShell is parsed as data; this script does not execute downloaded candidates.
$ErrorActionPreference='Stop'
$UARDName='UARD (Untrapped Auto-Repair Diagnostic)';$UARDVersion='1.1.1';$Root=Split-Path -Parent $MyInvocation.MyCommand.Path
$Middleman='https://untrapped-update-middleman-000-999-production.up.railway.app';$ArtifactBase=$Middleman+'/v1/artifact/'
$Report=Join-Path $Root 'repair-success-latest.txt';$BackupRoot=Join-Path $Root 'repair-backups';$ReportDir=Join-Path $Root 'uaud-reports';New-Item -ItemType Directory -Path $ReportDir -Force|Out-Null
$log=New-Object 'System.Collections.Generic.List[string]';$changed=$false;$failed=$false;$unknown=$false;$CanonicalCache=@{};$sw=[Diagnostics.Stopwatch]::StartNew();$MaxBytes=8388608
$ExpectedVersion='3.2.0';$ExpectedProtocol=3;$ExpectedBaseline='1.0.0';$RepeatedErrorThreshold=5;$GlobalRepairCeiling=200
$ErrorLibraryPath=Join-Path $Root 'error-library.jsonl';$ErrorLibrary=Join-Path $Root 'ErrorLibrary.ps1';if(Test-Path -LiteralPath $ErrorLibrary){. $ErrorLibrary}
function Log([string]$m){$x='['+(Get-Date -Format HH:mm:ss)+'] '+$m;Write-Host $x;[void]$log.Add($x);if((Get-Command Test-ErrorLike -ErrorAction SilentlyContinue) -and (Test-ErrorLike $m)){$fp=if(Get-Command Get-ErrorFingerprint -ErrorAction SilentlyContinue){Get-ErrorFingerprint $m}else{''};if($fp -and (Get-Command Save-ErrorEvent -ErrorAction SilentlyContinue)){[void](Save-ErrorEvent -Source 'UARD' -Stream 'Host' -Text $m -Artifact 'UARD' -CandidateHash '' -PreviousCandidateHash '' -Attempt 0 -Context 'live UARD output')}}}
function HashBytes([byte[]]$b){$s=[Security.Cryptography.SHA256]::Create();try{return ([BitConverter]::ToString($s.ComputeHash($b))).Replace('-','').ToLowerInvariant()}finally{$s.Dispose()}}
function HashText([string]$s){HashBytes ([Text.Encoding]::UTF8.GetBytes($s))}
function ReadLimited([IO.Stream]$st){$ms=New-Object IO.MemoryStream;$buf=New-Object byte[] 65536;$total=0;try{while(($r=$st.Read($buf,0,$buf.Length)) -gt 0){$total+=$r;if($total -gt $MaxBytes){throw "canonical artifact exceeds $MaxBytes byte limit"};$ms.Write($buf,0,$r)};return $ms.ToArray()}finally{$ms.Dispose()}}
function Normalize([byte[]]$b,[string]$n,[string]$t){if($t -eq 'json'){try{$null=([Text.Encoding]::UTF8.GetString($b).TrimStart([char]0xFEFF)|ConvertFrom-Json -ErrorAction Stop)}catch{throw "invalid canonical JSON for $n"};return $b};$s=[Text.Encoding]::UTF8.GetString($b).TrimStart([char]0xFEFF).Trim();if(-not $s.StartsWith('{')){return $b};try{$j=$s|ConvertFrom-Json -ErrorAction Stop}catch{return $b};if($null -eq $j -or $j -isnot [psobject]){return $b};$lang='';if($j.PSObject.Properties.Name -contains 'language'){$lang=[string]$j.language}elseif($j.PSObject.Properties.Name -contains 'lang'){$lang=[string]$j.lang};if($lang.ToLowerInvariant() -notin @('powershell','powershell-script','powershellscript','ps1','pwsh')){return $b};$enc='';if($j.PSObject.Properties.Name -contains 'encoding'){$enc=[string]$j.encoding};foreach($k in @('powershell','script','source','code','content','text','body')){if($j.PSObject.Properties.Name -contains $k -and $j.$k -is [string]){$v=[string]$j.$k;if($enc.ToLowerInvariant().Replace('-','') -eq 'base64'){$v=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($v))};return [Text.Encoding]::UTF8.GetBytes($v.TrimEnd()+"`n")}};if($j.PSObject.Properties.Name -contains 'commands' -and $j.commands -is [array] -and @($j.commands|Where-Object{$_ -isnot [string]}).Count -eq 0){return [Text.Encoding]::UTF8.GetBytes((($j.commands -join "`n").TrimEnd()+"`n"))};return $b}
function RemoteBytes([string]$n,[string]$t){if($CanonicalCache.ContainsKey($n)){return $CanonicalCache[$n]};for($a=1;$a -le 5;$a++){try{Log ('FETCH '+$n+' attempt '+$a+'/5');$q=[Net.HttpWebRequest]::Create($ArtifactBase+$n+'?cb='+[DateTime]::UtcNow.Ticks);$q.Method='GET';$q.Timeout=30000;$q.ReadWriteTimeout=30000;$q.UserAgent='UARD/1.1.1';$q.AllowAutoRedirect=$false;$r=$q.GetResponse();try{$v=[string]$r.Headers['X-Untrapped-Version'];$pr=[int]$r.Headers['X-Untrapped-Protocol'];$bl=[string]$r.Headers['X-Untrapped-Baseline'];if($v -ne $ExpectedVersion -or $pr -ne $ExpectedProtocol -or $bl -ne $ExpectedBaseline){throw "middleman identity mismatch: version=$v protocol=$pr baseline=$bl"};if($r.ContentLength -gt $MaxBytes){throw "canonical artifact exceeds $MaxBytes byte limit"};$raw=ReadLimited $r.GetResponseStream();$sha=[string]$r.Headers['X-Untrapped-SHA256'];if($sha -and $sha -ne (HashBytes $raw)){throw 'middleman SHA256 header mismatch'};$x=Normalize $raw $n $t}finally{$r.Dispose()};$CanonicalCache[$n]=$x;Log ('DOWNLOAD OK '+$n+' '+$x.Length+' bytes SHA256='+(HashBytes $x));return $x}catch{$c=0;$detail=$_.Exception.Message;$resp=$_.Exception.Response;try{$c=[int]$resp.StatusCode}catch{};if(Get-Command Save-ErrorEvent -ErrorAction SilentlyContinue){[void](Save-ErrorEvent -Source 'UARD' -Stream 'HTTP' -Text $detail -Artifact $n -HttpStatus $c -Attempt $a -Context 'canonical fetch')};if($c -in @(409,422,404,401,403,301,302,307,308)){Log ('DETERMINISTIC FETCH FAILURE '+$n+' HTTP '+$c+': '+$detail);$script:unknown=$true;return $null};if($c -eq 408 -or $c -eq 425 -or $c -eq 429 -or $c -ge 500 -or $c -eq 0){Log ('TRANSIENT FETCH ERROR '+$n+' HTTP '+$c+'; retrying. '+$detail);if($a -lt 5){Start-Sleep -Seconds ([Math]::Min($a*2,8));continue}}else{Log ('CANONICAL FETCH ERROR '+$n+' HTTP '+$c+': '+$detail)};break}};$script:unknown=$true;Log ('UNVERIFIED '+$n+' canonical source unavailable.');return $null}
function ParsePS([string]$s){$tokens=$null;$errors=$null;$ast=[System.Management.Automation.Language.Parser]::ParseInput($s,[ref]$tokens,[ref]$errors);[pscustomobject]@{pass=(@($errors).Count -eq 0);ast=$ast;errors=@($errors|ForEach-Object{[ordered]@{message=$_.Message;line=$_.Extent.StartLineNumber;column=$_.Extent.StartColumnNumber}})}}
function AstSignature([System.Management.Automation.Language.Ast]$ast){@($ast.FindAll({param($n)$n -is [System.Management.Automation.Language.CommandAst] -or $n -is [System.Management.Automation.Language.CommandParameterAst] -or $n -is [System.Management.Automation.Language.StringConstantExpressionAst] -or $n -is [System.Management.Automation.Language.ConstantExpressionAst]},$true)|ForEach-Object{if($_ -is [System.Management.Automation.Language.CommandAst]){'CMD|'+$_.GetCommandName()+'|'+(($_.CommandElements|ForEach-Object{$_.ToString().Trim()}) -join ' ')}elseif($_ -is [System.Management.Automation.Language.CommandParameterAst]){'PARAM|'+$_.ParameterName}else{'VAL|'+$_.ToString().Trim()}})}
function AstEquivalent([string]$candidate,[string]$canonical){$a=ParsePS $candidate;$b=ParsePS $canonical;if(-not $a.pass -or -not $b.pass){return $false};$sa=@(AstSignature $a.ast);$sb=@(AstSignature $b.ast);if($sa.Count -ne $sb.Count){return $false};for($i=0;$i -lt $sa.Count;$i++){if($sa[$i] -ne $sb[$i]){return $false}};return $true}
function RepairScript([string]$source,[object]$pr){$out=$source;foreach($e in @($pr.errors)){if($e.message -match '(?i)missing.*closing.*brace'){$out=$out.TrimEnd()+"`n}"}elseif($e.message -match '(?i)missing.*closing.*parenthesis'){$out=$out.TrimEnd()+"`n)"}elseif($e.message -match '(?i)missing.*closing.*bracket'){$out=$out.TrimEnd()+"`n]"}else{return $null}};if($out -eq $source){return $null};return $out}
function ValidateScript([string]$Candidate,[string]$Canonical,[string]$Artifact){$source=[IO.File]::ReadAllText($Candidate,[Text.Encoding]::UTF8);$canonicalSource=[IO.File]::ReadAllText($Canonical,[Text.Encoding]::UTF8);$history=New-Object 'System.Collections.Generic.List[object]';$counts=@{};$previousHash='';for($attempt=1;$attempt -le $GlobalRepairCeiling;$attempt++){$h=HashText $source;Log ('SYNTAX '+$Artifact+' attempt '+$attempt+' hash='+$h);$pr=ParsePS $source;if($pr.pass){Log ('SYNTAX PASS '+$Artifact);if(AstEquivalent $source $canonicalSource){Log ('AST EQUIVALENCE PASS '+$Artifact);return [pscustomobject]@{pass=$true;source=$source;attempts=$attempt;history=@($history);verdict=if($attempt -eq 1){'SUCCESS'}else{'SYNTAX_REPAIR_SUCCESS'}}};Log ('CANONICAL_MISMATCH '+$Artifact);return [pscustomobject]@{pass=$false;source=$source;attempts=$attempt;history=@($history);verdict='CANONICAL_MISMATCH'}};$new=$null;$cooked=$false;foreach($e in @($pr.errors)){$fp=if(Get-Command Get-ErrorFingerprint -ErrorAction SilentlyContinue){Get-ErrorFingerprint $e.Message 'PARSER'}else{HashText ('PARSER|'+$e.Message)};if(-not $counts.ContainsKey($fp)){$counts[$fp]=0};$counts[$fp]++;$history.Add([ordered]@{attempt=$attempt;fingerprint=$fp;message=$e.Message;line=$e.line;column=$e.column});if(Get-Command Save-ErrorEvent -ErrorAction SilentlyContinue){[void](Save-ErrorEvent -Source 'UARD' -Stream 'Parser' -Text $e.Message -Artifact $Artifact -CandidateHash $h -PreviousCandidateHash $previousHash -Attempt $attempt -SyntaxResult 'FAIL' -Context ("line=$($e.line) column=$($e.column)"))};if($counts[$fp] -ge $RepeatedErrorThreshold){$cooked=$true}};if($cooked){Log ('COOKED_REPEATED_ERROR '+$Artifact);return [pscustomobject]@{pass=$false;source=$source;attempts=$attempt;history=@($history);verdict='COOKED_REPEATED_ERROR'}};$new=RepairScript $source $pr;if($null -eq $new){Log ('NO_SAFE_REPAIR '+$Artifact);return [pscustomobject]@{pass=$false;source=$source;attempts=$attempt;history=@($history);verdict='UNKNOWN_ERROR'}};$nr=ParsePS $new;if(@($nr.errors).Count -ge @($pr.errors).Count){Log ('NON_PROGRESSING_REPAIR '+$Artifact);return [pscustomobject]@{pass=$false;source=$source;attempts=$attempt;history=@($history);verdict='NON_PROGRESSING_REPAIR'}};$previousHash=$h;$source=$new;[IO.File]::WriteAllText($Candidate,$source,(New-Object Text.UTF8Encoding($false)))};[pscustomobject]@{pass=$false;source=$source;attempts=$GlobalRepairCeiling;history=@($history);verdict='EMERGENCY_CEILING'}}
function Backup([string]$p){if(Test-Path -LiteralPath $p){$d=Join-Path $BackupRoot (Get-Date -Format 'yyyyMMdd-HHmmssfff');New-Item -ItemType Directory -Path $d -Force|Out-Null;Copy-Item -LiteralPath $p -Destination (Join-Path $d (Split-Path $p -Leaf)) -Force;Log ('BACKUP '+$p)}}
function Install([string]$p,[byte[]]$b){$d=Split-Path -Parent $p;if(-not(Test-Path -LiteralPath $d)){New-Item -ItemType Directory -Path $d -Force|Out-Null};$tmp=$p+'.uaudtmp-'+[Guid]::NewGuid().ToString('N');try{[IO.File]::WriteAllBytes($tmp,$b);if((HashBytes ([IO.File]::ReadAllBytes($tmp))) -ne (HashBytes $b)){throw 'temporary write verification hash mismatch'};Move-Item -LiteralPath $tmp -Destination $p -Force}finally{Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue}}
function PolicyDiag{$l=Get-ExecutionPolicy -List|Out-String;Log ('EXECUTION POLICY '+(($l.Trim()-replace '\r?\n',' | ')));$lm=$ExecutionContext.SessionState.LanguageMode;Log ('LANGUAGE MODE '+$lm);if($lm -ne 'FullLanguage'){$script:unknown=$true;Log 'APPLICATION CONTROL / CONSTRAINED LANGUAGE DETECTED; not bypassing it.'}}
function ToolDiag{$ps=Get-Command powershell.exe -ErrorAction SilentlyContinue;if($ps){Log ('POWERSHELL '+$ps.Source)}else{Log 'POWERSHELL.EXE NOT FOUND';$script:failed=$true}}
function WriteReportSafe([string]$diagnosis){try{@($UARDName+' ver '+$UARDVersion+' - TRUE BASELINE','Run: '+(Get-Date),'Diagnosis: '+$diagnosis,'Middleman: '+$Middleman,'Syntax, ErrorLibrary and AST equivalence gates active.','Behavioural gate: EXTERNAL_ISOLATED_WINDOWS_CI; candidate is not executed by UARD.','Protected boundary unchanged.','',$log)|Set-Content -LiteralPath $Report -Encoding UTF8;try{Start-Process notepad.exe -ArgumentList @($Report)|Out-Null}catch{}}catch{}}
try{Log ($UARDName+' ver '+$UARDVersion+' - TRUE BASELINE');Log ('MIDDLEMAN '+$Middleman);Log 'PROTECTION: no Windows Firewall/WFP/DNS/routes/Hosts/proxy/VPN/adapter/override-policy changes.';PolicyDiag;ToolDiag
$core=@('config.json','packet-filter.ps1','self-repair.ps1','status-untrapped.ps1','ultra-mode.ps1','ErrorLibrary.ps1','UAUD-validate.ps1');foreach($n in $core){$p=Join-Path $Root $n;$t=if($n -eq 'config.json'){'json'}else{'ps1'};$x=RemoteBytes ('ultra-mode/'+$n) $t;if($null -eq $x){continue};$tmp=Join-Path $env:TEMP ('UARD-'+[Guid]::NewGuid().ToString('N')+'-'+(Split-Path $n -Leaf));$canon=$null;try{[IO.File]::WriteAllBytes($tmp,$x);if($t -eq 'ps1'){$canon=Join-Path $env:TEMP ('UARD-CANON-'+[Guid]::NewGuid().ToString('N')+'-'+(Split-Path $n -Leaf));[IO.File]::WriteAllBytes($canon,$x);$result=ValidateScript $tmp $canon $n;if(-not $result.pass){$script:failed=$true;Log ('REJECTED '+$n+' verdict='+$result.verdict);continue};$finalBytes=[Text.Encoding]::UTF8.GetBytes($result.source);if(-not(AstEquivalent $result.source ([Text.Encoding]::UTF8.GetString($x)))){throw 'AST equivalence final gate failed'};if((Test-Path -LiteralPath $p) -and (HashBytes ([IO.File]::ReadAllBytes($p))) -eq (HashBytes $finalBytes)){Log ('CURRENT '+$n)}else{Backup $p;Install $p $finalBytes;$script:changed=$true;Log ('REPAIRED '+$n)}}else{$canonObj=$null;try{$canonObj=[Text.Encoding]::UTF8.GetString($x)|ConvertFrom-Json -ErrorAction Stop}catch{Log ('REJECTED INVALID JSON '+$n);$script:failed=$true;continue};$curObj=$null;if(Test-Path -LiteralPath $p){try{$curObj=[Text.Encoding]::UTF8.GetString([IO.File]::ReadAllBytes($p))|ConvertFrom-Json -ErrorAction Stop}catch{}};if($null -ne $curObj -and (($curObj|ConvertTo-Json -Depth 20) -eq ($canonObj|ConvertTo-Json -Depth 20))){Log ('CURRENT '+$n)}else{Backup $p;Install $p $x;$script:changed=$true;Log ('REPAIRED '+$n)}}}finally{Remove-Item $tmp -Force -ErrorAction SilentlyContinue;if($canon){Remove-Item $canon -Force -ErrorAction SilentlyContinue}}}
foreach($n in @('WinDivert.dll','WinDivert64.sys')){$f=Get-ChildItem -LiteralPath $Root -Filter $n -File -Recurse -ErrorAction SilentlyContinue|Select-Object -First 1;if($f){Log ('NATIVE OK '+$n)}else{Log ('NATIVE MISSING '+$n);$script:failed=$true}}
try{$probe=Join-Path $Root ('.uaud-write-test-'+[Guid]::NewGuid().ToString('N'));[IO.File]::WriteAllText($probe,'ok');if((Get-Content -LiteralPath $probe -Raw) -ne 'ok'){throw 'write/read verification mismatch'};Remove-Item $probe -Force;Log 'WRITE ACCESS OK'}catch{Log ('WRITE ACCESS FAILED: '+$_.Exception.Message);$script:failed=$true}
$diagnosis='NO REPAIR REQUIRED';if($failed){$diagnosis='REPAIR INCOMPLETE'}elseif($unknown){$diagnosis='VERIFICATION INCOMPLETE'}elseif($changed){$diagnosis='REPAIR SUCCESS'};Log ('[DIAGNOSIS] '+$diagnosis);$sw.Stop();Log ('RUNTIME '+$sw.Elapsed.ToString());if($changed -or $failed -or $unknown){WriteReportSafe $diagnosis};if($failed){exit 1};if($unknown){exit 2};exit 0}catch{Log ('FATAL GUARD: '+$_.Exception.GetType().FullName+': '+$_.Exception.Message);$sw.Stop();WriteReportSafe 'FATAL GUARD TRIPPED';exit 1}
